import json
import re
import html
from typing import Union
from urllib.parse import quote

from splunk.pdf.pdfgen_utils import get_user_info, get_server_info, getLogger
from splunk.util import normalizeBoolean

logger = getLogger()
READ_ONLY_TOKEN_NAMESPACES = {"env"}

FIND_TOKEN_REGEX = r"\$([ \w.-]+:)?((?=[\w.-])[\w .-]*[\w.-])(\|[|a-zA-Z]+)?\$"
FILTER_DELIMITER = "|"


def has_token(token: str) -> bool:
    """
    Return true if string contains any tokens.
    That is, any character(s) that start and end with a $ character
    """
    return re.search(FIND_TOKEN_REGEX, token) is not None


def find_tokens(value: str) -> list:
    return re.findall(FIND_TOKEN_REGEX, value)


def apply_filter(filter, token_values):
    filtered = []
    for token in token_values:
        if filter == "s":
            filtered.append(f'"{token}"')
        elif filter == "h":
            filtered.append(html.escape(token))
        elif filter == "u":
            filtered.append(quote(token, safe=""))
        else:
            filtered.append(token)

    return filtered


def apply_token_filters(filters: list, token_value):
    if isinstance(token_value, int):
        token_value = str(token_value)

    if not isinstance(token_value, list):
        token_value = [token_value]

    for filter in filters:
        token_value = apply_filter(filter, token_value)

    token_value = ",".join(token_value)

    return token_value


def replace_tokens_using_regex(value: str, token_values: dict):
    tokens_in_value = find_tokens(value)
    for token in tokens_in_value:
        namespace, name, filters = token
        token_name = namespace + name
        token_filters = filters.split(FILTER_DELIMITER)
        token_value = token_values.get(token_name)
        if token_value is None:
            continue

        # rebuild the string that needs to be replaced with the value
        token_string = "$" + token_name + filters + "$"

        # if the entire value is just a token that is a number we want to skip stringifing and filtering
        if isinstance(token_value, int) and value == token_string:
            return token_value

        # replace the token_string with the token_values with filters applied
        value = value.replace(token_string, apply_token_filters(token_filters, token_value))

    return value


def replace_tokens_in_value(value: str, token_values: dict, start: int = 0):
    """
    Returns value with tokens replaced with their values
    """
    # no $, we can assume no tokens
    first = value.find("$", start)
    if first == -1:
        return value

    # if next character after first $ is also a $, then it is not a token and move on
    if len(value) > (first + 1) and value[first + 1] == "$":
        new_value = value[0:first] + value[(first + 1) :]
        return replace_tokens_in_value(new_value, token_values, first + 1)

    # move end pointer to second $ occurrence from start
    second = value.find("$", first + 1)
    if second == -1:
        return value

    # needed to handle case for potential attached tokens (i.e. $token1$$token2$)
    next_first = second + 1
    next_second = value.find("$", next_first + 1)
    next_token = value[next_first : next_second + 1]

    # we can resolve current token if either attached to another token or attached to a "$$"
    token_attached = (
        re.search(FIND_TOKEN_REGEX, next_token)
        or len(value) > second + 2
        and (value[second + 1] == "$" and value[second + 2] == "$")
    )

    # if this token is attached to another or the next character is NOT a $ we can continue parsing
    next_character = value[second + 1] if len(value) > second + 1 else ""
    if token_attached or next_character != "$":
        token_portion = value[first : second + 1]
        resolved_token_portion = token_portion

        # if this is definitely a valid token lets process it
        if re.search(FIND_TOKEN_REGEX, token_portion):
            resolved_token_portion = replace_tokens_using_regex(token_portion, token_values)

        # if the token_portion still matches we just move to the next token start position
        if token_portion == resolved_token_portion:
            next_start = second + 1 if token_attached else second
            return replace_tokens_in_value(value, token_values, next_start)

        # if the entirety of the value we're replacing is the token, just return the
        # resolved token value, it could be a number and we don't want it stringified
        if token_portion == value:
            return resolved_token_portion

        # replace the token with the resolved value
        new_value = f"{value[0: first]}{resolved_token_portion}{value[second+1:]}"

        # move the new start position to be right after the resolved portion
        diff = len(str(resolved_token_portion)) - len(token_portion)
        new_start = second + diff + 1

        return replace_tokens_in_value(new_value, token_values, new_start)

    return replace_tokens_in_value(value, token_values, second)


def get_environment_tokens(session_key: str, namespace: str, dashboard_name: str):
    """
    Gets standard environment tokens as mentioned here excluding locale
    https://docs.splunk.com/Documentation/Splunk/8.2.1/Viz/tokens#Use_global_tokens_to_access_environment_information
    """
    environment_tokens = {"env:app": namespace, "env:page": dashboard_name}
    try:
        server_info = get_server_info(session_key)
        if server_info is not None:
            product_type = server_info.get("product_type")
            environment_tokens["env:product"] = product_type
            environment_tokens["env:version"] = server_info.get("version")

            is_product_types = ["enterprise", "hunk", "lite", "lite_free"]
            if product_type in is_product_types:
                environment_tokens["env:is_{}".format(product_type)] = "true"

            instance_type = server_info.get("instance_type")
            if instance_type:
                environment_tokens["env:instance_type"] = instance_type
                if instance_type == "cloud":
                    environment_tokens["env:is_cloud"] = "true"

            if normalizeBoolean(server_info.get("isFree")):
                environment_tokens["env:is_free"] = "true"

        user = get_user_info(session_key)
        if user is not None:
            environment_tokens["env:user"] = user.get("username")
            environment_tokens["env:user_realname"] = user.get("realname")
            environment_tokens["env:user_email"] = user.get("email")

    except Exception as e:
        logger.error("Exception while fetching environment tokens: %s", str(e))

    return environment_tokens


def get_input_values(definition: dict) -> dict:
    """
    Create a dictionary of input values and their default definitions. If no default
    definition exists, the input is not added. If the input is a time range, separate
    the earliest and latest values in the dictionary.
    """
    inputs = definition.get("inputs", {})
    input_values = {}
    for input_key in inputs:
        input_type = inputs[input_key].get("type")
        default_value = inputs[input_key].get("options", {}).get("defaultValue")
        token_name = inputs[input_key].get("options", {}).get("token")
        token_namespace = inputs[input_key].get("options", {}).get("tokenNamespace")
        # tokens in readonly namespaces shouldn't be modifiable by inputs
        if token_namespace not in READ_ONLY_TOKEN_NAMESPACES and token_name is not None:
            if input_type == "input.dimensionFilter" or input_type == "input.dimensionMultiFilter":
                dimension = inputs[input_key].get("options", {}).get("dimension", "")
                input_values[token_name] = default_value if default_value else "*"
                input_values[f"{token_name}.dimension"] = dimension
            elif default_value is not None:
                if token_namespace is not None:
                    token_name = "{}:{}".format(token_namespace, token_name)
                if input_type == "input.timerange":
                    input_values[token_name + ".earliest"] = default_value.split(",")[0].strip()
                    input_values[token_name + ".latest"] = default_value.split(",")[1].strip()
                else:
                    input_values[token_name] = default_value
    return input_values

def get_default_token_values(definition: dict) -> dict:
    """
    Create a dictionary of tokens and their default values.
    """
    default_token_namespaces = definition.get("defaults", {}).get("tokens", {})
    default_token_values = {}
    for namespace_key in default_token_namespaces:
        namespace_tokens = default_token_namespaces.get(namespace_key, {})
        for token_name in namespace_tokens:
            token_value = namespace_tokens[token_name].get("value")
            token_namespace = None if namespace_key == "default" else namespace_key
            # tokens in readonly namespaces shouldn't be modifiable by defaults
            if token_namespace not in READ_ONLY_TOKEN_NAMESPACES:
                if token_name is not None and token_value is not None:
                    if token_namespace is not None:
                        token_name = "{}:{}".format(token_namespace, token_name)
                    default_token_values[token_name] = token_value
    return default_token_values


def replace_tokens_in_dict(definition: Union[dict, str, int, list], token_values: dict, recursion_level=0):
    max_recursion_level = 10  # Same limit as in UDF

    if isinstance(definition, str):
        definition = replace_tokens_in_value(definition, token_values)
    elif isinstance(definition, list) and recursion_level <= max_recursion_level:
        for i, value in enumerate(definition):
            definition[i] = replace_tokens_in_dict(value, token_values, recursion_level + 1)
    elif isinstance(definition, dict) and recursion_level <= max_recursion_level:
        for key, value in definition.items():
            definition[key] = replace_tokens_in_dict(value, token_values, recursion_level + 1)
    return definition


def replace_tokens(definition: dict, session_key: str, namespace: str, dashboard_name: str, save_snapshot: bool = False) -> None:
    """
    Replace tokens in dataSources, defaults, and visualizations with the default values of tokens
    defined in the definition. Modifies the original definition.
    Note that in the following example, a token with an int type will remain an int
        definition = { "count": "$token$" }
    Whereas in the following example, a token with an int type will be converted to a string
        definition = { "query": "index = $token$" }
    """
    token_values = {}
    token_values.update(get_input_values(definition))
    token_values.update(get_default_token_values(definition))
    token_values.update(get_environment_tokens(session_key, namespace, dashboard_name))

    if save_snapshot:
        replace_tokens_in_dict(definition.get("dataSources", {}), token_values)
        replace_tokens_in_dict(definition.get("defaults", {}).get("dataSources", {}), token_values)
    else:
        replace_tokens_in_dict(definition, token_values)


def create_tokens_from_results(fields: list, columns: list, job, namespace: Union[str, None] = None) -> dict:
    """
    uses the fields, column, and job metadata to create tokens. These may be inserted
    into a dashboard definition to replace $dsName:job.sid$ tokens
    """
    tokens = {}

    for i, field in enumerate(fields):
        tokens[f"result.{field.get('name', '')}"] = str(columns[i][0])

    tokens.update(create_job_tokens(fields, job, "done"))

    if namespace and tokens:
        namespaced_tokens = {}
        for token in tokens:
            namespaced_tokens[f"{namespace}:{token}"] = tokens[token]
        tokens = namespaced_tokens

    return tokens


def create_job_tokens(fields: list, job, status="done") -> dict:
    """creates job tokens from fields and job metadata"""
    tokens = {
        "job.sid": str(job.sid),
        "job.status": status,
        "job.hasResults": "true" if job.resultCount > 0 else "false",
        "job.resultCount": str(job.resultCount),
        "job.isRealTimeSearch": "true" if job.isRealTimeSearch else "false",
        "job.lastUpdated": str(job.latestTime),
        "job.fields": ",".join(map(lambda field: field.get('name', ''), fields)),
        "job.startTime": str(job.createTime),
    }

    if status == "done":
        tokens["job.done"] = "true"
        tokens["job.percentComplete"] = "100"
    elif status == "failed":
        tokens["job.failed"] = "true"
        tokens["job.percentComplete"] = "0"

    if job.messages is not None:
        tokens["job.messages"] = ",".join(job.messages)

    return tokens


def get_namespaced_tokens(value: str) -> list:
    """returns array of tokens that have a namespace, i.e. separated by a :"""
    tokens = []

    for match in re.finditer(FIND_TOKEN_REGEX, value):
        token_name = match[0]
        if len(token_name.split(":")) > 1:
            tokens.append(token_name)

    return tokens

def disable_search_inputs(definition: dict) -> None:
    """Disables all inputs for tokens that are used in searches. Inputs are disabled using `options.isDisabled`"""
    datasources = json.dumps(definition.get("dataSources", {}))
    default_datasources = json.dumps(definition.get("defaults", {}).get("dataSources", {}))
    
    tokens_in_datasources = find_tokens(datasources + default_datasources)

    token_names_in_datasources = set()
    for token in tokens_in_datasources:
        namespace, name, filters = token
        token_name = namespace + name
        token_names_in_datasources.add(token_name)

    inputs = definition.get("inputs", {})
    for input_key in inputs:
        input = inputs[input_key]
        input_type = input.get("type")
        input_options = input.get("options", {})
        token_name = input_options.get("token")
        token_namespace = input_options.get("tokenNamespace")

        if token_name is not None:
            is_token_in_datasources = False
            if token_namespace is not None:
                token_name = "{}:{}".format(token_namespace, token_name)
            if input_type == "input.timerange":
                is_token_in_datasources = (
                    ((token_name + ".earliest") in token_names_in_datasources) or 
                    ((token_name + ".latest") in token_names_in_datasources))
            else:
                is_token_in_datasources = token_name in token_names_in_datasources
            if is_token_in_datasources:
                input_options["isDisabled"] = True
